<?php
/** "My shipping addresses" block shared by ClientDashboard and UserHome. Expects $d['addresses'] (sl_customerAddresses()) and $d['locker']. */
$slAddr = (array) sl_get($d, 'addresses', []);
$slA0 = $slAddr[0] ?? null;
?>
<section class="col g12" aria-label="My shipping addresses" id="addresses" data-sl-tabs><div class="row between wrap g8"><div><h2 class="sl-ct">My shipping addresses</h2><div class="mut sm">Paste one at checkout. Your suite number is the same in every country.</div></div><?php if ($slA0): ?><button class="sl-btn sm ghost" type="button" data-sl-copy="<?= h($slA0['full']) ?>"><i class="ic ic-sm i-copy" aria-hidden="true"></i>Copy full address</button><?php endif; ?></div>
<?php if (!$slA0): ?><div class="sl-card sl-empty mut sm">No warehouse address is set up yet.</div><?php else: ?>
<div class="ad-card"><div class="ad-main"><div class="ad-tabs"><?php foreach ($slAddr as $i => $a): ?><span class="<?= $i === 0 ? 'on' : '' ?>" data-sl-tab="addr<?= $i ?>" role="button" tabindex="0" style="cursor:pointer"><i class="ic ic-sm <?= h($a['icon']) ?>" aria-hidden="true"></i><?= h($a['label']) ?></span><?php endforeach; ?></div>
<?php foreach ($slAddr as $i => $a): ?><div class="ad-lines" data-sl-tabpanel="addr<?= $i ?>" <?= $i ? 'hidden' : '' ?>><?php foreach (['Recipient' => $a['recipient'], 'Address 1' => $a['address1'], 'Address 2' => $a['address2'], 'City' => $a['city'], 'State / ZIP' => $a['zip'], 'Phone' => $a['phone']] as $k => $v): if ($v === '') continue; ?><div class="ad-ln"><small><?= h($k) ?></small><span class="fw5"><?= h($v) ?></span><button type="button" aria-label="Copy <?= h($k) ?>" data-sl-copy="<?= h($v) ?>"><i class="ic ic-sm i-copy" aria-hidden="true"></i></button></div><?php endforeach; ?></div><?php endforeach; ?></div>
<div class="ad-side"><div class="col g4"><small style="font-size:13px;letter-spacing:.06em;text-transform:uppercase;opacity:.6">Your suite</small><span class="ad-suite"><?= sl_v($d, 'locker') ?></span><span class="sm" style="opacity:.7"><?= h($slA0['note']) ?></span></div><div class="ad-bc" aria-hidden="true"></div><span class="mono sm" style="opacity:.7"><?= h(mb_strtoupper($slA0['label'])) ?> · <?= sl_v($d, 'locker') ?></span></div></div>
<?php if (count($slAddr) > 1): ?><div class="ad-more"><?php foreach (array_slice($slAddr, 1) as $a): ?><div class="ad-m"><div class="row between"><span class="cc"><?= h($a['cc']) ?></span><button class="sl-ib" type="button" aria-label="Copy <?= h($a['label']) ?> address" data-sl-copy="<?= h($a['full']) ?>"><i class="ic ic-sm i-copy" aria-hidden="true"></i></button></div><b class="fw5"><?= h($a['label']) ?></b><span class="mut sm"><?= h($a['city']) ?></span></div><?php endforeach; ?></div><?php endif; ?>
<div class="mut sm">New addresses appear here as soon as we add them.</div><?php endif; ?></section>
